import json
import re
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

# Node params arrive in the `params` dict (sandbox-bootstrap.py), not as variables.
mode = params["mode"]
request = params.get("request")
start_date = params.get("start_date")
end_date = params.get("end_date")
plan = params.get("plan")
pieces = params.get("pieces")

CAMPAIGNS = "social_campaigns"
PIECES = "social_content_pieces"
MAX_PIECES = 20
TYPES = {"social_post": "Social media post", "article": "Article", "email": "Email", "announcement": "Announcement", "visual": "Visual"}
CHANNELS = {"instagram": "Instagram", "facebook": "Facebook", "linkedin": "LinkedIn", "google_business": "Google Business", "email": "Email", "website": "Website", "print": "Print"}
SOCIAL_CHANNELS = ["instagram", "facebook", "linkedin", "google_business"]
DEFAULT_SOCIAL = ["instagram", "facebook", "linkedin"]
OBJECTIVES = ["awareness", "leads", "promotion", "event", "announcement", "retention"]
CADENCES = ["even", "countdown", "front_loaded"]
TEAM_WRITES = ["write it ourselves", "write them ourselves", "we'll write", "we will write", "we write", "write it myself", "i'll write", "i will write", "our team will write", "team will write", "team writes", "written by our team", "written by the team", "don't draft", "do not draft", "no draft"]


def text(value):
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return ", ".join(str(v) for v in value)
    return str(value).strip()


def as_list(value):
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    return [part.strip() for part in text(value).replace(",", "\n").splitlines() if part.strip()]


def as_date(value):
    raw = text(value)[:10]
    if not raw:
        return None
    try:
        return date.fromisoformat(raw)
    except ValueError:
        pass
    # dd/mm/yyyy by hand: datetime.strptime imports _strptime, which the automation sandbox blocks.
    match = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", raw)
    if not match:
        return None
    try:
        return date(int(match.group(3)), int(match.group(2)), int(match.group(1)))
    except ValueError:
        return None


def add_business_days(day, count):
    step = 1 if count >= 0 else -1
    remaining = abs(count)
    while remaining > 0:
        day = day + timedelta(days=step)
        if day.weekday() < 5:
            remaining -= 1
    return day


def move_missing(data, fields):
    """A field holding a [[MISSING: ...]] note is left empty and the note goes to missing_info, so the record
    shows real values only and the open questions in one place."""
    notes = [line for line in text(data.get("missing_info")).splitlines() if line.strip()]
    for field in fields:
        value = text(data.get(field))
        if "[[missing" in value.lower():
            data.pop(field, None)
            note = re.sub(r"\[\[\s*missing\s*:?\s*", "", value, flags=re.IGNORECASE).replace("]]", "").strip()
            notes.append(note if note else field)
    if notes:
        data["missing_info"] = chr(10).join(notes)[:4000]
    return data


def no_draft(item):
    """True when the plan says this piece is written by the team, whatever field name the agent used."""
    for key in ("draft", "draft_required", "needs_draft", "generate_draft", "draft_automatically"):
        if item.get(key) is False or text(item.get(key)).lower() in ("false", "no"):
            return True
    who = (text(item.get("author")) + " " + text(item.get("written_by"))).lower()
    return any(word in who for word in ("self", "team", "business", "ourselves", "client"))


def keys_in(values, allowed):
    out = []
    for value in as_list(values):
        key = value.lower().replace(" ", "_")
        if key in allowed and key not in out:
            out.append(key)
    return out


settings = api.extension.settings() or {}
folder = text(settings.get("knowledge_folder")) or "Social posts"
zone = ZoneInfo(text(settings.get("time_zone")) or "Australia/Sydney")
try:
    lead = int(settings.get("review_lead_days") or 2)
except (TypeError, ValueError):
    lead = 2
today = datetime.now(zone).date()
earliest = add_business_days(today, lead + 1)

# Every mode assigns every output.
ready = False
problem = ""
brand = {}
brief_request = {}
rules = {}
usable = False
issues = []
checked = []
table_markdown = ""
plan_markdown = ""
piece_count = 0
campaign_id = ""
created = 0
existing = 0

if mode == "context":
    try:
        brand = json.loads(api.files.read(file=f"{folder}/Brand Kit/brand-kit.json"))
    except Exception:
        brand = {}
    asked = text(request)
    if not brand.get("company_name"):
        problem = "There is no confirmed Brand Kit yet. Create one under Records > Brand Kits and confirm it, then start the campaign again."
    elif not asked:
        problem = "Describe the campaign (what it promotes, when and for whom), then start it again."
    else:
        ready = True
    start = as_date(start_date)
    end = as_date(end_date)
    brief_request = {
        "request": asked,
        "start_date": start.isoformat() if start else "",
        "end_date": end.isoformat() if end else "",
        "today": today.isoformat(),
    }
    rules = {
        "content_types": TYPES,
        "channels": CHANNELS,
        "social_channels": SOCIAL_CHANNELS,
        "default_social_channels": DEFAULT_SOCIAL,
        "objectives": OBJECTIVES,
        "cadences": CADENCES,
        "max_pieces": MAX_PIECES,
        "earliest_publish_date": earliest.isoformat(),
        "review_lead_business_days": lead,
        "default_cta": text(brand.get("default_cta")) or text(settings.get("default_cta")),
        "default_cta_url": text(brand.get("default_cta_url")),
    }

elif mode == "check":
    items = [p for p in (pieces or []) if isinstance(p, dict)]
    if len(items) > MAX_PIECES:
        issues.append(f"The plan has {len(items)} pieces; only the first {MAX_PIECES} are kept.")
        items = items[:MAX_PIECES]
    campaign = plan if isinstance(plan, dict) else {}
    start = as_date(campaign.get("start_date"))
    end = as_date(campaign.get("end_date"))
    for index, item in enumerate(items, start=1):
        # The planning agent does not always use the exact field names, so accept the common variants.
        title = (text(item.get("title")) or text(item.get("name")) or text(item.get("headline")) or text(item.get("topic")))[:200]
        if not title:
            # No title at all: use the start of the angle (up to its first colon or full stop), else the campaign name and position.
            angle_text = text(item.get("angle") or item.get("description") or item.get("summary"))
            first = re.split(r"[:.]", angle_text, maxsplit=1)[0].strip()
            words = first.split()
            title = (" ".join(words[:10]) + ("..." if len(words) > 10 else "")) if words else ""
            title = (title or ((text(campaign.get("name")) or "Campaign") + " post " + str(index)))[:200]
        content_type = text(item.get("content_type") or item.get("type")).lower().replace(" ", "_").replace("-", "_")
        if not content_type:
            content_type = "social_post"
        content_type = {"social_media_post": "social_post", "post": "social_post", "linkedin_post": "social_post", "social": "social_post",
                        "blog": "article", "blog_post": "article", "newsletter": "email", "image": "visual", "graphic": "visual"}.get(content_type, content_type)
        if not title or content_type not in TYPES:
            issues.append(f"Piece {index} was dropped: it needs a title and one of these content types: {', '.join(TYPES)}.")
            continue
        channels = keys_in(item.get("channels") or item.get("channel"), CHANNELS) or keys_in(campaign.get("channels") or campaign.get("channel"), CHANNELS)
        if content_type == "social_post":
            social = [c for c in channels if c in SOCIAL_CHANNELS]
            if not social:
                issues.append(f"'{title}' had no channels in the plan, so it uses the default social channels; ask for changes if that is wrong.")
            channels = social or DEFAULT_SOCIAL
        topic = text(item.get("topic")) or text(campaign.get("topic"))
        publish = as_date(item.get("publish_date"))
        if publish is None or publish < earliest:
            issues.append(f"'{title}' moved to {earliest.strftime('%d/%m/%Y')}: the earliest publish date leaves {lead} business days for review.")
            publish = earliest
        if end and publish > end:
            issues.append(f"'{title}' is dated after the campaign ends ({end.strftime('%d/%m/%Y')}).")
        checked.append({
            "title": title,
            "content_type": content_type,
            "channels": channels,
            "publish_date": publish.isoformat(),
            "topic": topic[:200],
            "angle": text(item.get("angle"))[:2000],
            "cta": text(item.get("cta"))[:200],
            "cta_url": text(item.get("cta_url"))[:500],
            "draft": not no_draft(item),
        })
    checked.sort(key=lambda p: p["publish_date"])
    asked = text(request).lower().replace(chr(8217), "'")
    team_writes = any(phrase in asked for phrase in TEAM_WRITES)
    if team_writes and checked and all(item["draft"] for item in checked):
        if len(checked) == 1:
            checked[0]["draft"] = False
            issues.append(f"'{checked[0]['title']}' is calendar only: the request says the team will write it.")
        else:
            issues.append("The request says the team will write a piece, but the plan does not say which one; ask for changes to mark it.")
    total = len(checked)
    for position, item in enumerate(checked, start=1):
        item["sequence"] = f"{position} of {total}"
    piece_count = total
    usable = total > 0
    if not usable:
        issues.append("The plan has no usable pieces.")
    rows = ["| # | Publish date | Content type | Channels | Piece | Drafted? | Angle |", "|---|---|---|---|---|---|---|"]
    for position, item in enumerate(checked, start=1):
        when = date.fromisoformat(item["publish_date"]).strftime("%a %d/%m/%Y")
        chans = ", ".join(str(CHANNELS.get(c) or c) for c in item["channels"]) or "-"
        angle = item["angle"].replace("|", "/").replace("\n", " ")[:160]
        rows.append(f"| {position} | {when} | {TYPES[item['content_type']]} | {chans} | {item['title'].replace('|', '/')} | {'Yes' if item.get('draft', True) else 'No, calendar only'} | {angle} |")
    table_markdown = "\n".join(rows)
    # The whole plan document, built here so blank optional fields are skipped: the platform's template
    # renderer refuses any placeholder that resolves to an empty value (template-render.ts).
    def line_if(label, value):
        return ["**" + label + ":** " + text(value), ""] if text(value) else []
    when_bits = [d.strftime("%d/%m/%Y") for d in (start, end) if d]
    doc = ["# Campaign plan: " + (text(campaign.get("name")) or "Untitled campaign"), ""]
    doc += line_if("What is being promoted", campaign.get("topic"))
    doc += line_if("Dates", " to ".join(when_bits))
    doc += line_if("Audience", campaign.get("audience"))
    doc += line_if("Call to action", campaign.get("cta"))
    doc += line_if("Frequency", campaign.get("frequency"))
    doc += ["## Pieces (" + str(piece_count) + ")", "", table_markdown, ""]
    if issues:
        doc += ["## Notes", ""] + ["- " + i for i in issues] + [""]
    missing_list = as_list(campaign.get("missing"))
    if missing_list:
        doc += ["## Missing information", ""] + ["- " + m for m in missing_list] + [""]
    doc += ["---", "", "*Planned by the Social Media Agent for review. Approving creates one Content piece per row; each is drafted and reviewed separately. Nothing is posted for you.*"]
    plan_markdown = "\n".join(doc)

elif mode == "create":
    campaign = plan if isinstance(plan, dict) else {}
    name = text(campaign.get("name"))[:200] or "Campaign"
    start = as_date(campaign.get("start_date"))
    end = as_date(campaign.get("end_date"))
    key_day = as_date(campaign.get("key_date"))
    data = {
        "topic": text(campaign.get("topic"))[:4000],
        "audience": text(campaign.get("audience"))[:4000],
        "frequency": text(campaign.get("frequency"))[:200],
        "cta": text(campaign.get("cta"))[:200],
        "offer_details": text(campaign.get("offer_details"))[:4000],
        "offer_terms": text(campaign.get("offer_terms"))[:4000],
        "missing_info": "\n".join(as_list(campaign.get("missing")))[:4000],
        "posts_count": len([p for p in (pieces or []) if isinstance(p, dict)]),
        "channels": keys_in(campaign.get("channels"), CHANNELS),
        "content_types": keys_in(campaign.get("content_types"), TYPES),
    }
    if start:
        data["start_date"] = start.isoformat()
    if end:
        data["end_date"] = end.isoformat()
    if key_day:
        data["key_date"] = key_day.isoformat()
        data["key_date_label"] = text(campaign.get("key_date_label"))[:200]
    if text(campaign.get("objective")) in OBJECTIVES:
        data["objective"] = text(campaign.get("objective"))
    if text(campaign.get("cadence")) in CADENCES:
        data["cadence"] = text(campaign.get("cadence"))
    if text(campaign.get("cta_url")).startswith("http"):
        data["cta_url"] = text(campaign.get("cta_url"))
    try:
        brand_version = json.loads(api.files.read(file=f"{folder}/Brand Kit/brand-kit.json")).get("version")
        if isinstance(brand_version, int):
            data["brand_kit_version"] = brand_version
    except Exception:
        pass
    data = {k: v for k, v in data.items() if v not in ("", [], None)}
    data = move_missing(data, ("topic", "audience", "frequency", "cta", "offer_details", "offer_terms"))

    # Retries are recognised by this job's run id, never by name: a new job with the same campaign name and
    # dates is a new campaign. Each piece key is "<run id>:<campaign id>:<position>", so a retried step finds
    # the campaign it already made from its own pieces and the unique key refuses a duplicate piece.
    run_id = text(dict(trigger).get("runId")) or "manual"
    cursor = None
    for _ in range(10):
        page = api.records.list(type_slug=PIECES, limit=200, cursor=cursor) or {}
        for row in page.get("records") or []:
            key = text((row.get("data") or {}).get("piece_key"))
            if key.startswith(run_id + ":") and key.count(":") >= 2:
                campaign_id = key.split(":")[1]
                break
        cursor = page.get("nextCursor")
        if campaign_id or not cursor:
            break
    if not campaign_id:
        made = api.records.create(type_slug=CAMPAIGNS, record={"title": name, "stage": "planned", "data": data}) or {}
        campaign_id = text((made.get("record") or made).get("id"))
    if not campaign_id:
        raise RuntimeError("The campaign record could not be created.")

    for item in [p for p in (pieces or []) if isinstance(p, dict)]:
        piece_data = {
            "content_type": item.get("content_type"),
            "channels": item.get("channels") or [],
            "origin": "campaign",
            "publish_date": item.get("publish_date"),
            "topic": text(item.get("topic")),
            "angle": text(item.get("angle")),
            "brief": text(campaign.get("topic")),
            "cta": text(item.get("cta")) or text(campaign.get("cta")),
            "sequence": text(item.get("sequence")),
            "generate_draft": item.get("draft") is not False,
            "piece_key": f"{run_id}:{campaign_id}:{text(item.get('sequence')).split(' ')[0]}",
        }
        link = text(item.get("cta_url")) or text(campaign.get("cta_url"))
        if link.startswith("http"):
            piece_data["cta_url"] = link
        piece_data = {k: v for k, v in piece_data.items() if v not in ("", [], None)}
        piece_data = move_missing(piece_data, ("topic", "angle", "brief", "cta"))
        try:
            api.records.create(type_slug=PIECES, record={"title": text(item.get("title")), "stage": "planned", "data": piece_data, "links": {"campaign": [campaign_id]}})
            created += 1
        except Exception as error:
            # The piece key is unique within the table: a retry that already made this piece is refused, not duplicated.
            if "unique" in str(error).lower():
                existing += 1
            else:
                raise

else:
    raise RuntimeError(f"Unknown mode '{mode}'.")
